const protectedCompany = new Set(['empresa-panel','vacantes','nueva-vacante','postulantes','informe','configuracion-empresa']);

function icon(name){
  const paths={search:'<circle cx="11" cy="11" r="7"></circle><path d="m20 20-3.5-3.5"></path>',pin:'<path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"></path><circle cx="12" cy="10" r="2"></circle>',clock:'<circle cx="12" cy="12" r="9"></circle><path d="M12 7v5l3 2"></path>',brief:'<rect x="3" y="7" width="18" height="13" rx="2"></rect><path d="M8 7V4h8v3M3 12h18"></path>',user:'<circle cx="12" cy="8" r="4"></circle><path d="M4 21a8 8 0 0 1 16 0"></path>',check:'<path d="m5 12 4 4L19 6"></path>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"></path>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"></rect><path d="M5 10a7 7 0 0 0 14 0M12 17v4"></path>',code:'<path d="m8 9-4 3 4 3M16 9l4 3-4 3M14 5l-4 14"></path>',chevron:'<path d="m9 18 6-6-6-6"></path>',settings:'<circle cx="12" cy="12" r="3"></circle><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-1.6v-.2h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"></path>',camera:'<path d="M14.5 4 16 7h3a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2h3l1.5-3Z"></path><circle cx="12" cy="13" r="3"></circle>',logout:'<path d="M10 17l5-5-5-5M15 12H3M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"></path>'};
  return `<svg aria-hidden="true" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.brief}</svg>`;
}

function setSession(role){
  appState.session={role,name:role==='student'?'Favio':'Nexa Digital'};
  sessionStorage.setItem('talenti-demo-session',JSON.stringify(appState.session));
}
function clearSession(){
  appState.session=null;
  appState.returnTo=null;
  appState.pendingAction=null;
  sessionStorage.removeItem('talenti-demo-session');
  location.hash='inicio';
}
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2600)}
function closeModal(){modalBackdrop.hidden=true;modalContent.innerHTML=''}
function openModal(html){modalContent.innerHTML=`<button class="modal-close" data-close-modal aria-label="Cerrar">×</button>${html}`;modalBackdrop.hidden=false;setTimeout(()=>modalContent.querySelector('button,input')?.focus(),20)}

function accessModal(action='continuar',returnTo=location.hash){
  appState.returnTo=returnTo;
  appState.pendingAction=action;
  openModal(`<div class="modal-icon">T</div><span class="eyebrow">Acceso necesario</span><h2 id="modalTitle">Ingresa para ${action}</h2><p>Podrás continuar desde este mismo punto después de acceder a Talenti.</p><button class="btn btn-primary btn-block" data-open-login>Ingresar</button><button class="btn btn-secondary btn-block" data-route-modal="registro">Crear cuenta de estudiante</button><button class="text-button" data-close-modal>Seguir explorando</button>`);
}
function loginModal(){
  openModal(`<div class="modal-icon">T</div><span class="eyebrow">Bienvenido nuevamente</span><h2 id="modalTitle">Ingresa a Talenti</h2><p>En el prototipo puedes usar los datos de demostración.</p><form id="loginForm" novalidate><div class="field"><label for="loginEmail">Correo electrónico</label><input id="loginEmail" type="email" value="favio@demo.pe" required><small class="field-error" id="loginEmailError"></small></div><div class="field"><label for="loginPassword">Contraseña</label><input id="loginPassword" type="password" value="talenti123" minlength="6" required><small class="field-error" id="loginPasswordError"></small></div><div class="demo-note"><strong>Cuenta de demostración</strong><br>Correo: favio@demo.pe · Contraseña: talenti123</div><button class="btn btn-primary btn-block" type="submit">Ingresar como estudiante</button></form><button class="btn btn-secondary btn-block" data-company-login>Ingresar como empresa</button><button class="text-button" data-route-modal="registro">¿No tienes cuenta? Crear cuenta</button>`);
  modalContent.querySelector('#loginForm').onsubmit=e=>{
    e.preventDefault();
    const email=modalContent.querySelector('#loginEmail');
    const pass=modalContent.querySelector('#loginPassword');
    let valid=true;
    document.querySelector('#loginEmailError').textContent='';document.querySelector('#loginPasswordError').textContent='';
    if(!email.value || !/^\S+@\S+\.\S+$/.test(email.value)){document.querySelector('#loginEmailError').textContent='Ingresa un correo válido.';email.classList.add('invalid');valid=false}else email.classList.remove('invalid');
    if(pass.value.length<6){document.querySelector('#loginPasswordError').textContent='La contraseña debe tener al menos 6 caracteres.';pass.classList.add('invalid');valid=false}else pass.classList.remove('invalid');
    if(!valid)return;
    setSession('student');closeModal();showToast('Ingreso correcto. Bienvenido a Talenti.');
    const next=appState.returnTo||'#panel';appState.returnTo=null;location.hash=next.replace('#','');
  };
}

function renderHeader(active=''){
  const brand=`<a class="brand" href="#${appState.session?.role==='student'?'panel':appState.session?.role==='company'?'empresa-panel':'inicio'}" aria-label="Ir al inicio de Talenti"><span class="brand-mark">T</span><span>Talenti</span></a>`;
  if(!appState.session){
    topbar.innerHTML=`${brand}<nav class="main-nav" id="mainNav" aria-label="Navegación principal"><a class="${active==='oportunidades'?'active':''}" href="#oportunidades">Oportunidades</a><a class="${active==='funcionamiento'?'active':''}" href="#funcionamiento">Cómo funciona</a><a class="${active==='empresa-publica'?'active':''}" href="#empresa-publica">Para empresas</a><a class="${active==='planes'?'active':''}" href="#planes">Planes</a></nav><div class="header-actions"><button class="btn btn-ghost" data-open-login>Ingresar</button><button class="btn btn-primary" data-route="registro">Crear cuenta</button><button class="menu-button" data-menu aria-label="Abrir menú" aria-expanded="false">☰</button></div>`;
  }else if(appState.session.role==='student'){
    const items=[['panel','Inicio'],['oportunidades-panel','Oportunidades'],['procesos','Mis procesos'],['preparacion','Preparación']];
    topbar.innerHTML=`${brand}<nav class="main-nav private-nav" id="mainNav" aria-label="Navegación del estudiante">${items.map(([r,l])=>`<a class="${active===r?'active':''}" href="#${r}">${l}</a>`).join('')}</nav><div class="header-actions"><button class="icon-button ${active==='notificaciones'?'active':''}" data-route="notificaciones" aria-label="Notificaciones">${icon('bell')}<span class="notification-dot"></span></button><div class="profile-menu"><button class="profile-trigger" data-profile-menu aria-expanded="false"><span class="mini-avatar">FS</span><span class="profile-name">Favio</span><span aria-hidden="true">⌄</span></button><div class="profile-dropdown" id="profileDropdown" hidden><button data-route="perfil">${icon('user')} Mi perfil técnico</button><button data-route="configuracion">${icon('settings')} Configuración</button><button data-logout>${icon('logout')} Cerrar sesión</button></div></div><button class="menu-button" data-menu aria-label="Abrir menú" aria-expanded="false">☰</button></div>`;
  }else{
    const items=[['empresa-panel','Resumen'],['vacantes','Vacantes'],['postulantes','Postulantes']];
    topbar.innerHTML=`${brand}<nav class="main-nav private-nav" id="mainNav" aria-label="Navegación de la empresa">${items.map(([r,l])=>`<a class="${active===r?'active':''}" href="#${r}">${l}</a>`).join('')}</nav><div class="header-actions"><div class="profile-menu"><button class="profile-trigger" data-profile-menu aria-expanded="false"><span class="mini-avatar">ND</span><span class="profile-name">Nexa Digital</span><span aria-hidden="true">⌄</span></button><div class="profile-dropdown" id="profileDropdown" hidden><button data-route="configuracion-empresa">${icon('settings')} Configuración</button><button data-logout>${icon('logout')} Cerrar sesión</button></div></div><button class="menu-button" data-menu aria-label="Abrir menú" aria-expanded="false">☰</button></div>`;
  }
}

function footer(){return `<footer class="footer"><div class="container footer-row"><div><strong>Talenti</strong> · Tu código demuestra tu talento</div><div>Prototipo académico · Información simulada</div></div></footer>`}
function breadcrumb(items){return `<nav class="breadcrumbs" aria-label="Ruta de navegación">${items.map((x,i)=>i===items.length-1?`<span aria-current="page">${x[1]}</span>`:`<button data-route="${x[0]}">${x[1]}</button><span>/</span>`).join('')}</nav>`}
function appPage(active,content){renderHeader(active);main.innerHTML=`<div class="private-page"><div class="container">${content}</div></div>`;bindView()}
function publicPage(active,content){renderHeader(active);main.innerHTML=`<div class="page">${content}${footer()}</div>`;bindView()}

function jobCard(j,showMatch=false){
  return `<article class="job-card" tabindex="0" data-job="${j.id}" aria-label="Ver ${j.title}"><div class="company-logo">${j.logo}</div><div><p class="muted">${j.published}</p><h3>${j.title}</h3><p><strong>${j.company}</strong></p><div class="meta"><span>${icon('pin')} ${j.location}</span><span>${icon('brief')} ${j.mode}</span>${showMatch?`<span class="match-score">${j.match}% compatible</span>`:''}</div><p class="muted card-summary">${j.summary}</p><div>${j.skills.map(s=>`<span class="badge">${s}</span>`).join('')}</div></div><button class="save-button" data-save="${j.id}" aria-label="Guardar oportunidad">♡</button></article>`;
}

function home(){
  publicPage('inicio',`<section class="hero"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow">Prácticas para estudiantes de programación</span><h1 class="title-xl">Encuentra una práctica que valore lo que sabes hacer</h1><p class="lead">Explora oportunidades, presenta tus proyectos y avanza por un proceso claro de evaluación y entrevista.</p><div class="button-row"><button class="btn btn-primary" data-route="oportunidades">Buscar prácticas</button><button class="btn btn-secondary" data-route="funcionamiento">Conocer el proceso</button></div><div class="trust-row"><span>${icon('check')} Explora sin registrarte</span><span>${icon('check')} Postula cuando estés listo</span></div></div><div class="hero-panel"><h2 class="title-md">Busca tu próxima práctica</h2><p class="muted">Puedes revisar todas las oportunidades antes de crear una cuenta.</p><div class="search-box"><div class="input-wrap">${icon('search')}<input id="heroQuery" placeholder="Puesto o tecnología" aria-label="Puesto o tecnología"></div><div class="input-wrap">${icon('pin')}<select id="heroLocation" aria-label="Ubicación"><option>Todo el Perú</option><option>Lima</option><option>Arequipa</option><option>Remoto</option></select></div><button class="btn btn-primary" id="heroSearch">Buscar</button></div><div class="quick-tags"><button class="chip" data-search-tag="Frontend">Frontend</button><button class="chip" data-search-tag="Backend">Backend</button><button class="chip" data-search-tag="Remoto">Remoto</button></div>${jobCard(jobs[0],false)}</div></div></section><section class="section"><div class="container"><span class="eyebrow">Una sola ruta</span><h2 class="title-lg">De tu perfil a una oportunidad compatible</h2><div class="steps-grid"><article class="step-card"><div class="step-number">1</div><h3>Explora</h3><p>Compara oportunidades por tecnología, modalidad y ubicación.</p></article><article class="step-card"><div class="step-number">2</div><h3>Demuestra</h3><p>Presenta proyectos y completa las evaluaciones solicitadas.</p></article><article class="step-card"><div class="step-number">3</div><h3>Avanza</h3><p>Revisa cada etapa y permite que la empresa tome una decisión informada.</p></article></div></div></section><section class="feature-band"><div class="container feature-grid"><div><span class="eyebrow light">Talenti te acompaña</span><h2 class="title-lg">Practica antes de ser evaluado</h2><p>El simulador libre es privado. La entrevista evaluada solo comienza después de una introducción, una pregunta de ensayo y la verificación de cámara y micrófono.</p></div><div class="feature-list"><div class="feature-item"><span class="check">✓</span><div><strong>Práctica libre</strong><br><span>Repite preguntas y recibe recomendaciones privadas.</span></div></div><div class="feature-item"><span class="check">✓</span><div><strong>Proceso transparente</strong><br><span>Conoce el tiempo, las reglas y la siguiente etapa.</span></div></div><div class="feature-item"><span class="check">✓</span><div><strong>Decisión humana</strong><br><span>La empresa revisa los resultados y toma la decisión final.</span></div></div></div></div></section>`);
}

function opportunities(query='',privateView=false){
  const filtered=jobs.filter(j=>(j.title+j.company+j.skills.join(' ')+j.mode).toLowerCase().includes(query.toLowerCase()));
  const content=`<section class="page-head"><div class="container"><span class="eyebrow">Oportunidades</span><h1 class="title-lg">Prácticas de programación</h1><p class="muted">Encuentra oportunidades alineadas con tus intereses y disponibilidad.</p><div class="search-box"><div class="input-wrap">${icon('search')}<input id="resultQuery" value="${query}" placeholder="Puesto, empresa o tecnología"></div><div class="input-wrap">${icon('pin')}<select><option>Todo el Perú</option><option>Lima</option><option>Arequipa</option><option>Remoto</option></select></div><button class="btn btn-primary" id="resultSearch">Buscar</button></div></div></section><div class="container"><div class="results-layout"><aside class="filters" id="filters"><h2 class="title-md">Filtrar resultados</h2><div class="filter-group"><strong>Modalidad</strong><label><input type="checkbox"> Remoto</label><label><input type="checkbox"> Híbrido</label><label><input type="checkbox"> Presencial</label></div><div class="filter-group"><strong>Especialidad</strong><label><input type="checkbox"> Desarrollo web</label><label><input type="checkbox"> Desarrollo móvil</label><label><input type="checkbox"> Calidad de software</label></div><button class="btn btn-secondary btn-block" id="clearFilters">Limpiar filtros</button></aside><section><div class="results-top"><div><button class="btn btn-secondary mobile-filter" id="toggleFilters">Filtros</button><strong>${filtered.length} oportunidades encontradas</strong></div><select class="chip" aria-label="Ordenar"><option>${privateView?'Más compatibles':'Más recientes'}</option><option>${privateView?'Más recientes':'Por empresa'}</option></select></div><div class="jobs-list">${filtered.length?filtered.map(j=>jobCard(j,privateView)).join(''):`<div class="panel empty-state"><strong>No encontramos resultados</strong><span class="muted">Prueba con otra palabra o limpia los filtros.</span></div>`}</div></section></div></div>`;
  if(privateView){renderHeader('oportunidades-panel');main.innerHTML=`<div class="page private-list">${content}</div>`;bindView()}else publicPage('oportunidades',content);
}

function detail(id='frontend'){
  const j=jobs.find(x=>x.id===id)||jobs[0];
  const loggedStudent=appState.session?.role==='student';
  const active=loggedStudent?'oportunidades-panel':'oportunidades';
  const back=loggedStudent?'oportunidades-panel':'oportunidades';
  renderHeader(active);
  main.innerHTML=`<div class="page"><section class="page-head"><div class="container">${breadcrumb([[back,'Oportunidades'],['',j.title]])}<div class="job-title-row"><div class="company-logo">${j.logo}</div><div><span class="eyebrow">Prácticas preprofesionales</span><h1 class="title-lg">${j.title}</h1><p class="lead">${j.company}</p><div class="meta"><span>${icon('pin')} ${j.location}</span><span>${icon('brief')} ${j.mode}</span><span>${icon('clock')} Jornada completa</span></div></div></div></div></section><div class="container detail-layout"><article class="panel job-detail"><h2>Sobre la práctica</h2><p>${j.summary} Trabajarás con un equipo que brindará acompañamiento durante el aprendizaje y la ejecución de tareas.</p><h2>Lo que realizarás</h2><ul><li>Participar en el desarrollo y revisión de funcionalidades.</li><li>Organizar avances y documentar el trabajo realizado.</li><li>Coordinar tareas con el equipo de tecnología.</li></ul><h2>Requisitos principales</h2><ul>${j.skills.map(s=>`<li>Conocimientos de ${s}.</li>`).join('')}<li>Ser estudiante de una carrera relacionada con desarrollo de software.</li></ul><h2>Etapas de esta postulación</h2><div class="process-preview"><span><b>1</b> Perfil</span><span><b>2</b> Evaluación técnica</span><span><b>3</b> Preparación</span><span><b>4</b> Entrevista evaluada</span><span><b>5</b> Revisión empresarial</span></div></article><aside class="panel apply-panel"><span class="eyebrow">Compatibilidad</span><div class="compatibility"><strong>${loggedStudent?j.match:'—'}${loggedStudent?'%':''}</strong><div class="progress"><span style="width:${loggedStudent?j.match:20}%"></span></div><small>${loggedStudent?'Calculada con tu perfil actual.':'Inicia sesión para calcularla con tu perfil.'}</small></div><p><strong>Tecnologías solicitadas</strong></p><div class="skill-list">${j.skills.map(s=>`<span class="skill">${s}</span>`).join('')}</div><hr class="divider"><button class="btn btn-primary btn-block" data-apply="${j.id}">Postular ahora</button><button class="btn btn-secondary btn-block" data-save="${j.id}">Guardar oportunidad</button><p class="legal-note">Talenti apoya la evaluación. La empresa toma la decisión final de selección.</p></aside></div>${footer()}</div>`;
  bindView();
}

