function register(){
  appState.selectedRole='student';
  renderHeader('registro');
  main.innerHTML=`<section class="auth-page"><div class="auth-card wide"><span class="eyebrow">Crear cuenta</span><h1 class="title-lg">Empieza tu recorrido en Talenti</h1><div class="register-progress"><span class="active">1. Tipo de cuenta</span><span>2. Datos principales</span><span>3. Perfil</span></div><div class="role-options"><button class="role-card active" data-role="student"><strong>Soy estudiante</strong><br><span class="muted">Quiero encontrar prácticas</span></button><button class="role-card" data-role="company"><strong>Represento una empresa</strong><br><span class="muted">Quiero buscar practicantes</span></button></div><form id="registerForm" class="form-grid" novalidate><div class="field"><label for="regName">Nombres</label><input id="regName" value="Favio" required><small class="field-error"></small></div><div class="field"><label for="regLast">Apellidos</label><input id="regLast" value="Solorzano" required><small class="field-error"></small></div><div class="field full"><label for="regEmail">Correo electrónico</label><input id="regEmail" type="email" value="favio@demo.pe" required><small class="field-error"></small></div><div class="field full"><label for="regInstitution">Institución o empresa</label><input id="regInstitution" value="TECSUP" required><small class="field-error"></small></div><label class="check-row full"><input id="regTerms" type="checkbox" required> Acepto los términos de la demostración y el tratamiento de los datos simulados.</label><small class="field-error full" id="termsError"></small><div class="field full"><button class="btn btn-primary btn-block" type="submit">Crear cuenta y continuar</button></div></form><p class="legal-note center">Este prototipo no envía ni almacena información real.</p></div></section>`;
  document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{appState.selectedRole=b.dataset.role;document.querySelectorAll('[data-role]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#regInstitution').value=appState.selectedRole==='student'?'TECSUP':'Nexa Digital'});
  document.querySelector('#registerForm').onsubmit=e=>{
    e.preventDefault();let valid=true;
    document.querySelectorAll('#registerForm input[required]:not([type=checkbox])').forEach(input=>{const err=input.parentElement.querySelector('.field-error');err.textContent='';input.classList.remove('invalid');if(!input.value.trim() || (input.type==='email'&&!/^\S+@\S+\.\S+$/.test(input.value))){err.textContent=input.type==='email'?'Ingresa un correo válido.':'Este campo es obligatorio.';input.classList.add('invalid');valid=false}});
    const terms=document.querySelector('#regTerms');document.querySelector('#termsError').textContent=terms.checked?'':'Debes aceptar para continuar con la demostración.';if(!terms.checked)valid=false;
    if(!valid){showToast('Revisa los campos señalados.');return}
    setSession(appState.selectedRole);showToast('Cuenta de demostración creada correctamente.');location.hash=appState.selectedRole==='student'?'perfil':'empresa-panel';
  };
  bindView();
}

