function interviewIntro(){
  appState.cameraReady=false;appState.micReady=false;
  appPage('procesos',`${breadcrumb([['procesos','Mis procesos'],['proceso','Desarrollo Frontend'],['','Preparación de entrevista']])}<div class="narrow-content"><div class="app-header"><div><span class="eyebrow">Preparación obligatoria</span><h1 class="title-lg">Antes de tu entrevista evaluada</h1><p class="muted">Esta introducción no genera puntaje. Sirve para conocer la dinámica y probar tu equipo.</p></div></div><div class="intro-steps"><span class="active">1. Información</span><span>2. Equipo</span><span>3. Ensayo</span><span>4. Entrevista</span></div><section class="panel"><h2>¿Cómo será la entrevista?</h2><div class="summary-strip"><div><small>Duración</small><strong>15 minutos</strong></div><div><small>Preguntas</small><strong>5 preguntas</strong></div><div><small>Modalidad</small><strong>Voz y cámara</strong></div></div><div class="warning-callout"><strong>La sesión oficial será grabada.</strong><br>La empresa podrá revisar la grabación, las respuestas y el informe generado. La pregunta de ensayo no forma parte de la calificación.</div><h2>Comprueba tu equipo</h2><div class="device-grid"><button class="device-check" id="checkCamera">${icon('camera')}<span><strong>Cámara</strong><small>Presiona para comprobar</small></span><b id="cameraStatus">Comprobar</b></button><button class="device-check" id="checkMic">${icon('mic')}<span><strong>Micrófono</strong><small>Presiona para comprobar</small></span><b id="micStatus">Comprobar</b></button></div><label class="check-row consent-row"><input id="interviewConsent" type="checkbox"> Comprendo que la entrevista oficial será grabada y compartida con la empresa.</label><small class="field-error" id="interviewError"></small><div class="button-row end"><button class="btn btn-secondary" data-route="proceso">Volver</button><button class="btn btn-primary" id="goInterview" disabled>Continuar a pregunta de ensayo</button></div></section></div>`);
  const update=()=>{const ok=appState.cameraReady&&appState.micReady&&document.querySelector('#interviewConsent').checked;document.querySelector('#goInterview').disabled=!ok};
  document.querySelector('#checkCamera').onclick=()=>{appState.cameraReady=true;document.querySelector('#cameraStatus').textContent='Lista ✓';document.querySelector('#checkCamera').classList.add('ready');update()};
  document.querySelector('#checkMic').onclick=()=>{appState.micReady=true;document.querySelector('#micStatus').textContent='Listo ✓';document.querySelector('#checkMic').classList.add('ready');update()};
  document.querySelector('#interviewConsent').onchange=update;
  document.querySelector('#goInterview').onclick=()=>{appState.interviewReady=true;location.hash='entrevista'};
}
