function bindView(){
  document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>location.hash=el.dataset.route);
  document.querySelectorAll('[data-job]').forEach(el=>{el.onclick=e=>{if(e.target.closest('[data-save]'))return;location.hash=`detalle/${el.dataset.job}`};el.onkeydown=e=>{if(e.key==='Enter')location.hash=`detalle/${el.dataset.job}`}});
  document.querySelectorAll('[data-save]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(!appState.session)accessModal('guardar esta oportunidad',`#detalle/${b.dataset.save}`);else showToast('Oportunidad guardada en tu perfil.')});
  document.querySelectorAll('[data-apply]').forEach(b=>b.onclick=()=>{if(!appState.session)accessModal('postular a esta práctica',`#detalle/${b.dataset.apply}`);else if(appState.session.role!=='student')showToast('Cambia a una cuenta de estudiante para postular.');else confirmApplication(b.dataset.apply)});
  document.querySelectorAll('.demo-action').forEach(b=>b.onclick=()=>showToast('Acción simulada correctamente.'));
  document.querySelectorAll('.selectable-chips .chip').forEach(b=>b.onclick=()=>b.classList.toggle('active'));
}
function confirmApplication(id){
  const j=jobs.find(x=>x.id===id)||jobs[0];
  openModal(`<div class="modal-icon">${icon('brief')}</div><span class="eyebrow">Confirmar postulación</span><h2 id="modalTitle">${j.title}</h2><p>Se enviarán tu perfil técnico, CV y proyectos seleccionados. Después podrás seguir cada etapa desde “Mis procesos”.</p><div class="info-callout left">Tu perfil está 78 % completo. Puedes postular y actualizarlo posteriormente.</div><button class="btn btn-primary btn-block" id="confirmApply">Confirmar postulación</button><button class="text-button" data-close-modal>Revisar después</button>`);
}

function route(){
  window.scrollTo(0,0);
  const raw=location.hash.replace('#','')||'inicio';
  const [name,param]=raw.split('/');
  if(protectedStudent.has(name)&&appState.session?.role!=='student'){
    if(appState.session?.role==='company'){showToast('Esta sección pertenece a la cuenta del estudiante.');location.hash='empresa-panel';return}
    appState.returnTo=`#${raw}`;home();accessModal('acceder a esta sección',`#${raw}`);return;
  }
  if(protectedCompany.has(name)&&appState.session?.role!=='company'){
    if(appState.session?.role==='student'){showToast('Esta sección pertenece a la cuenta empresarial.');location.hash='panel';return}
    appState.returnTo=`#${raw}`;companyPublic();accessModal('acceder al panel empresarial',`#${raw}`);return;
  }
  if(name==='evaluacion'&&!appState.evaluationAuthorized){showToast('Primero revisa y acepta las condiciones de la evaluación.');location.hash='evaluacion-intro';return}
  if((name==='entrevista-intro'||name==='entrevista')&&appState.processStage==='evaluation'){showToast('Primero debes completar la evaluación técnica.');location.hash='proceso';return}
  if(name==='entrevista'&&!appState.interviewReady){showToast('Primero completa la verificación de cámara y micrófono.');location.hash='entrevista-intro';return}
  const routes={inicio:home,oportunidades:()=>opportunities('',false),detalle:()=>detail(param),funcionamiento:howItWorks,'empresa-publica':companyPublic,planes:plans,registro:register,panel:studentDashboard,'oportunidades-panel':()=>opportunities('',true),procesos:processes,proceso:processDetail,perfil:profile,preparacion:preparationHub,'practica-configurar':practiceSetup,practica:practiceSession,'evaluacion-intro':evaluationIntro,evaluacion:evaluationSession,'entrevista-intro':interviewIntro,entrevista:interviewSession,notificaciones:notifications,configuracion:settings,'empresa-panel':companyPanel,vacantes:vacancies,'nueva-vacante':newVacancy,postulantes:candidates,informe:report,'configuracion-empresa':companySettings};
  (routes[name]||home)();
}

document.addEventListener('click',e=>{
  const routeButton=e.target.closest('[data-route-modal]');if(routeButton){closeModal();location.hash=routeButton.dataset.routeModal}
  if(e.target.closest('[data-close-modal]'))closeModal();
  if(e.target.closest('[data-open-login]'))loginModal();
  if(e.target.closest('[data-company-login]')){setSession('company');closeModal();showToast('Ingreso empresarial correcto.');location.hash='empresa-panel'}
  if(e.target.closest('[data-logout]')){clearSession();showToast('Sesión cerrada correctamente.')}
  if(e.target.closest('[data-menu]')){const nav=document.querySelector('#mainNav');nav?.classList.toggle('open');e.target.closest('[data-menu]').setAttribute('aria-expanded',nav?.classList.contains('open'))}
  if(e.target.closest('[data-profile-menu]')){const drop=document.querySelector('#profileDropdown');if(drop){drop.hidden=!drop.hidden;e.target.closest('[data-profile-menu]').setAttribute('aria-expanded',!drop.hidden)}}
  if(e.target.id==='heroSearch'){const q=document.querySelector('#heroQuery').value;location.hash='oportunidades';setTimeout(()=>opportunities(q,false),20)}
  if(e.target.id==='resultSearch'){opportunities(document.querySelector('#resultQuery').value,appState.session?.role==='student')}
  if(e.target.dataset.searchTag!==undefined){location.hash='oportunidades';setTimeout(()=>opportunities(e.target.dataset.searchTag,false),20)}
  if(e.target.id==='toggleFilters')document.querySelector('#filters')?.classList.toggle('open');
  if(e.target.id==='clearFilters'){document.querySelectorAll('#filters input').forEach(x=>x.checked=false);showToast('Filtros limpiados.')}
  if(e.target.id==='confirmApply'){closeModal();showToast('Postulación enviada correctamente.');location.hash='proceso'}
  if(e.target.id==='confirmEvaluation'){appState.processStage='interview-ready';sessionStorage.setItem('talenti-process-stage',appState.processStage);closeModal();location.hash='proceso'}
  if(e.target.id==='officialInterviewDemo'){closeModal();openModal(`<div class="modal-icon">IA</div><span class="eyebrow">Entrevista evaluada</span><h2 id="modalTitle">Demostración del inicio oficial</h2><p>En la versión funcional comenzaría la grabación, el cronómetro y la primera pregunta personalizada.</p><button class="btn btn-primary btn-block" data-route-modal="proceso">Finalizar demostración</button>`)}
});
modalBackdrop.onclick=e=>{if(e.target===modalBackdrop)closeModal()};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
window.addEventListener('hashchange',route);
route();
